class BlueskyTest: XCTestCase {
    func testTapOpen() {
        let app = XCUIApplication()

        // Tap the Open button in the alert
        let openButton = app.alerts.buttons["Open"]
        if openButton.exists {
            openButton.tap()
        } else {
            // Try finding button by other means
            let buttons = app.buttons
